const out = {};
try { const c = require('crypto'); out.require_crypto = typeof c.createHmac; } catch (e) { out.require_crypto = 'ERR:' + e.message.slice(0, 80); }
try { out.subtle = typeof globalThis.crypto?.subtle; } catch (e) { out.subtle = 'ERR'; }
try { out.Buffer = typeof Buffer; } catch (e) { out.Buffer = 'ERR'; }
try { await new Promise(r => setTimeout(r, 150)); out.sleep = 'ok'; } catch (e) { out.sleep = 'ERR:' + e.message.slice(0, 80); }
try {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode('partnerkey'), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const sig = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode('123/api/v2/product/get_comment1700000000token456'));
  out.hmac_hex = Buffer.from(sig).toString('hex');
} catch (e) { out.hmac_hex = 'ERR:' + e.message.slice(0, 120); }
try {
  if (typeof require_crypto !== 'undefined') {}
  const nodeCrypto = require('crypto');
  out.hmac_create = nodeCrypto.createHmac('sha256', 'partnerkey').update('123/api/v2/product/get_comment1700000000token456').digest('hex');
} catch (e) { out.hmac_create = 'ERR:' + e.message.slice(0, 80); }
return [{ json: out }];

